	}

	/**
	 * Configures cert as the client certificate for subsequent TLS connections. The certificate must have access to its private key. Use this only when the server requests or requires client-certificate authentication. Important: Configure the client certificate before Connect or ConvertToSsl. A certificate without its private key cannot prove client identity.
	 * @see https://www.chilkatsoft.com/refdoc/phpCkSocketRef.html#SetSslClientCert
	 * @param CkCert $cert
	 * @return bool
	 */
	function SetSslClientCert($cert) {
		return CkSocket_SetSslClientCert($this->_cPtr,$cert);
	}

	/**
	 * Loads and configures a TLS client certificate and private key from PEM data or a PEM filename supplied in pemDataOrFilename. Use pemPassword when the private key is encrypted. Important: The PEM material must include or make available the private key corresponding to the certificate. Configure it before the TLS handshake begins.
	 * @see https://www.chilkatsoft.com/refdoc/phpCkSocketRef.html#SetSslClientCertPem
	 * @param ?string $pemDataOrFilename
	 * @param ?string $pemPassword
	 * @return bool
	 */
	function SetSslClientCertPem($pemDataOrFilename,$pemPassword) {
		return CkSocket_SetSslClientCertPem($this->_cPtr,$pemDataOrFilename,$pemPassword);
	}

	/**
	 * Loads and configures a TLS client certificate and private key from the PFX/P12 file pfxFilename, using pfxPassword. Use this only when the server requests or requires client-certificate authentication. Important: Protect PFX files and passwords because they contain private-key material.
	 * @see https://www.chilkatsoft.com/refdoc/phpCkSocketRef.html#SetSslClientCertPfx
	 * @param ?string $pfxFilename
	 * @param ?string $pfxPassword
	 * @return bool
	 */
	function SetSslClientCertPfx($pfxFilename,$pfxPassword) {
		return CkSocket_SetSslClientCertPfx($this->_cPtr,$pfxFilename,$pfxPassword);
	}

	/**
	 * Pauses the calling thread for approximately millisec milliseconds. This is a convenience method and does not perform network I/O or keep a connection alive. Important: Sleeping blocks the current thread. It is not a substitute for socket readiness methods, asynchronous I/O, or protocol timers.
	 * @see https://www.chilkatsoft.com/refdoc/phpCkSocketRef.html#SleepMs
	 * @param int $millisec
	 */
	function SleepMs($millisec) {
		CkSocket_SleepMs($this->_cPtr,$millisec);
	}

	/**
	 * Authenticates the SSH tunnel session as sshLogin using privateKey. Call SshOpenTunnel first. The SSH server must have the corresponding public key authorized for that account. Important: This authenticates the SSH transport used by the socket tunnel. It does not authenticate the final destination protocol reached through a forwarded channel.
	 * @see https://www.chilkatsoft.com/refdoc/phpCkSocketRef.html#SshAuthenticatePk
	 * @param ?string $sshLogin
	 * @param CkSshKey $privateKey
	 * @return bool
	 */
	function SshAuthenticatePk($sshLogin,$privateKey) {
		return CkSocket_SshAuthenticatePk($this->_cPtr,$sshLogin,$privateKey);
	}

	/**
	 * Creates an asynchronous task to call the SshAuthenticatePk method with the arguments provided.
	 * @see https://www.chilkatsoft.com/refdoc/phpCkSocketRef.html#SshAuthenticatePkAsync
	 * @param ?string $sshLogin
	 * @param CkSshKey $privateKey
	 * @return ?CkTask
	 */
	function SshAuthenticatePkAsync($sshLogin,$privateKey) {
