	}

	/**
	 * Authenticates the SSH tunnel session using sshLogin and sshPassword. Call SshOpenTunnel first and authenticate before opening forwarded channels. Important: Do not log or expose the SSH password. Public-key authentication is generally preferable when supported.
	 * @see https://www.chilkatsoft.com/refdoc/phpCkSocketRef.html#SshAuthenticatePw
	 * @param ?string $sshLogin
	 * @param ?string $sshPassword
	 * @return bool
