	}

	/**
	 * Moves the connection out of sock and into a newly created member of this object's socket set. After one or more successful calls, this object acts as a set of connected and/or listener sockets.
	 * @see https://www.chilkatsoft.com/refdoc/phpCkSocketRef.html#TakeSocket
	 * @param CkSocket $sock
	 * @return bool
	 */
	function TakeSocket($sock) {
		return CkSocket_TakeSocket($this->_cPtr,$sock);
	}

	/**
	 * Requests TLS renegotiation on an established TLS connection, causing another handshake to negotiate new security parameters where the protocol and peer support it. Important: TLS 1.3 does not use legacy renegotiation, and many modern TLS 1.2 servers disable it. The method can therefore fail even on an otherwise healthy TLS connection.
	 * @see https://www.chilkatsoft.com/refdoc/phpCkSocketRef.html#TlsRenegotiate
	 * @return bool
	 */
	function TlsRenegotiate() {
		return CkSocket_TlsRenegotiate($this->_cPtr);
	}

