	}

	/**
	 * Configures this socket to route subsequent Connect calls through the already connected and authenticated Ssh object. The destination host and port passed to Connect are reached by SSH port forwarding rather than by a direct TCP connection. This is one of several SSH-tunneling models in Chilkat. Alternatives include this class's SshOpenTunnel/SshNewChannel workflow and the separate SshTunnel class for background static or dynamic forwarding. Important: The supplied Ssh object must remain connected and authenticated while the forwarded socket connection is being established and used.
	 * @see https://www.chilkatsoft.com/refdoc/phpCkSocketRef.html#UseSsh
	 * @param CkSsh $ssh
	 * @return bool
	 */
	function UseSsh($ssh) {
		return CkSocket_UseSsh($this->_cPtr,$ssh);
	}
